const row = (concept, bullets, sourceBlocks, image = null) => ({ concept, bullets, sourceBlocks, ...(image ? { image } : {}) });
const fullImage = (path, caption, sourceCaption) => ({ path, position: 'after', size: 'large', layout: 'full_width', containsText: true, caption, sourceCaption });

const images = {
  sbar: fullImage('img/img_001.png', 'Transmission structurée SBAR à l’arrivée en SSPI', "TABLEAU 11.1 Exemple d'un protocole de transfert à la salle de réveil"),
  aldrete: fullImage('img/img_002.png', 'Score d’Aldrete modifié pour la sortie de phase 1', 'TABLEAU 11.2 Score Aldrete modifié'),
  fastTrack: fullImage('img/img_003.png', 'Score de transfert direct vers l’unité ambulatoire', "TABLEAU 11.3 Score modifié d'Aldrete déterminant les patients en chirurgie ambulatoire pouvant être transférés directement de la salle d'opération à l'unité de chirurgie ambulatoire"),
  sahsSeverity: fullImage('img/img_004.png', 'Sévérité du SAHS selon l’index apnées-hypopnées', "TABLEAU 11.4 Critère de sévérité du syndrome d'apnée-hypopnée du sommeil (SAHS)"),
  stopBang: fullImage('img/img_005.png', 'Critères du questionnaire STOP-BANG', 'TABLEAU 11.5 Questionnaire STOP-BANG: répondre oui ou non'),
  stopBangRisk: fullImage('img/img_006.png', 'Probabilité de SAHS selon le STOP-BANG', "TABLEAU 11.6 Indice de probabilité de la présence d'un syndrome d'apnée-hypopnée du sommeil (SAHS)"),
  sahsCare: fullImage('img/img_007.png', 'Surveillance postopératoire d’un patient avec SAHS', "FIGURE 11.1 Algorithme décisionnel sur la gestion périopératoire du patient avec syndrome d'apnée-hypopnée du sommeil (SAHS)"),
  sahsAmbu: fullImage('img/img_008.png', 'Éligibilité ambulatoire d’un patient avec SAHS', 'FIGURE 11.2 Algorithme décisionnel pour déterminer si le patient est un candidat à une chirurgie ambulatoire'),
  hypotension: fullImage('img/img_009.png', 'Démarche étiologique devant une hypotension en SSPI', "TABLEAU 11.7 Aide au diagnostic de l'hypotension artérielle en salle de réveil"),
  hypertensionCauses: fullImage('img/img_010.png', 'Causes d’hypertension en SSPI', "TABLEAU 11.8 Diagnostic différentiel de l'hypertension artérielle à la salle de réveil"),
  hypertensionDrugs: fullImage('img/img_011.png', 'Antihypertenseurs utilisables en SSPI', "TABLEAU 11.9 Options thérapeutiques de l'hypertension artérielle à la salle de réveil"),
  cardiac: fullImage('img/img_012.png', 'Stratégie de monitorage cardiaque postopératoire', 'FIGURE 11.3 Monitorage cardiaque postopératoire'),
  delayed: fullImage('img/img_013.png', 'Causes d’éveil retardé ou de coma', "TABLEAU 11.10 Causes les plus fréquentes d'éveil retardé ou de coma en salle de réveil"),
  renal: fullImage('img/img_014.png', 'Étiologies pré-rénales, rénales et post-rénales', "TABLEAU 11.11 Étiologies de l'insuffisance rénale postopératoire"),
};

function buildFiche() {
  const parts = [
    {
      title: 'Organiser la récupération et sécuriser le relais',
      sections: [
        { title: 'Trois phases, trois objectifs', rows: [
          row('Phase 1 · récupération précoce', ['Elle s’étend de la fin de l’anesthésie au retour des réflexes de protection et des fonctions motrices.', 'La priorité est la détection immédiate d’une défaillance respiratoire, circulatoire ou neurologique.'], ['b00003','b00004','b00005']),
          row('Phase 2 · aptitude à quitter l’hôpital', ['Elle commence après la phase 1 et s’achève lorsque la sortie hospitalière est sûre.', 'Douleur, nausées, saignement, stabilité et environnement du retour sont intégrés à la décision.'], ['b00005','b00018','b00019']),
          row('Phase 3 · convalescence', ['Elle couvre le retour progressif jusqu’à l’état fonctionnel préopératoire.', 'La sortie de SSPI ne signifie donc pas récupération complète.'], ['b00005']),
        ]},
        { title: 'Accueil en SSPI et responsabilité médicale', rows: [
          row('Structure et moyens', [{ text: 'Prévoir environ 1,5 à 2 lits de SSPI par salle d’opération.', children: ['Dimensionner l’unité sur le flux réel du bloc', 'Prévenir une attente non monitorée en sortie de salle'] }, 'Matériel de voies aériennes, réanimation et soutien hémodynamique doit être immédiatement disponible.'], ['b00006','b00007']),
          row('Transport accompagné', ['L’anesthésiologiste accompagne le patient et adapte oxygène et monitorage au risque du transfert.', 'Il reste responsable jusqu’au congé de SSPI ou au relais médical explicite.'], ['b00008']),
          row('Transmission SBAR', [{ text: 'La transmission intervient après installation de l’oxygène et des moniteurs requis.', children: ['Situation et intervention réalisée', 'Antécédents et problèmes périopératoires', 'Évaluation actuelle et bilan liquidien', 'Recommandations, ordonnances et examens attendus'] }, 'L’infirmière doit être disponible et apte à prendre effectivement le relais.'], ['b00008','b00009'], images.sbar),
          row('Ordonnances', ['Les prescriptions de SSPI sont rédigées avant que l’anesthésiste ne quitte l’unité.', 'Les éléments à surveiller et les seuils d’escalade doivent être explicites.'], ['b00008']),
        ]},
      ],
    },
    {
      title: 'Monitorage, critères de sortie et ambulatoire',
      sections: [
        { title: 'Surveillance de phase 1', rows: [
          row('Socle respiratoire', [{ text: 'La SpO2 est continue pendant la récupération initiale.', children: ['Vérifier la qualité du signal et la tendance', 'Réagir à toute désaturation plutôt qu’au chiffre isolé'] }, 'La capnographie est requise chez le patient intubé ou encore profondément sédaté.'], ['b00011']),
          row('Nourrisson à risque', ['Un moniteur d’apnée est présent avant 50 semaines d’âge gestationnel.', 'Le risque respiratoire impose une observation adaptée au terme corrigé.'], ['b00011']),
          row('Surveillance globale', [{ text: 'Rythme et pression sont suivis de façon routinière.', children: ['Fonction neuromusculaire et température', 'État mental, douleur et nausées-vomissements', 'Hydratation et capacité à uriner'] }, 'Les signes vitaux sont habituellement mesurés toutes les 15 minutes.'], ['b00011','b00014']),
        ]},
        { title: 'Sortie sûre de la SSPI', rows: [
          row('Délégation encadrée', [{ text: 'Une infirmière peut autoriser la sortie si une délégation écrite s’appuie sur un protocole validé.', children: ['Définir les critères de sortie', 'Préciser les situations exigeant un appel médical'] }, 'Sans examen médical final, les critères doivent rester objectifs et traçables.'], ['b00012','b00013']),
          row('Aldrete modifié', ['Le score combine activité, respiration, circulation, conscience et saturation.', 'Un total d’au moins 9 sur 10 permet la sortie de phase 1.'], ['b00013','b00015'], images.aldrete),
          row('Délais de sécurité', [{ text: 'Observer au moins 15 minutes après la dernière dose IV d’opioïde ou de sédatif.', children: ['Rechercher somnolence et bradypnée', 'Prolonger si la molécule agit plus longtemps'] }, 'Après arrêt de l’oxygène, conserver 15 minutes d’observation pour exclure une hypoxémie.'], ['b00014']),
          row('Bloc périphérique', ['Le pic plasmatique d’un anesthésique local survient vers 30 minutes.', 'Ce délai atteint environ 60 minutes avec adrénaline ou ropivacaïne.'], ['b00017']),
        ]},
        { title: 'Ambulatoire et voie rapide', rows: [
          row('Sortie hospitalière', [{ text: 'La sortie de phase 2 ajoute douleur, nausées-vomissements, saignement et stabilité globale.', children: ['Anticiper le trajet et l’accès aux soins', 'Vérifier la compréhension des consignes'] }, 'Hydratation orale et miction ne sont pas exigées systématiquement chez un patient sans risque.'], ['b00018','b00019']),
          row('Rétention urinaire', [{ text: 'Le patient consulte s’il n’urine pas dans les 6 à 8 heures.', children: ['Haut risque : miction avant la sortie et résidu < 300 mL', 'Volume vésical > 500–600 mL : cathétérisme'] }, 'Âge, sexe masculin, chirurgie pelvienne, neuraxiale, durée > 60 minutes et cristalloïdes > 750 mL augmentent le risque.'], ['b00019']),
          row('Consignes à domicile', [{ text: 'Donner des instructions écrites sur douleur, complications, suivi et urgence.', children: ['Préciser le numéro joignable', 'Faire reformuler les signes d’alerte'] }, 'Interdire conduite, alcool et machines dangereuses pendant les 24 premières heures et prévoir un accompagnant.'], ['b00020','b00021','b00022','b00023','b00024','b00025']),
          row('Fast-track', ['Un patient stable après bloc périphérique peut éviter la SSPI si douleur et nausées sont aussi évaluées.', 'Le score dédié exige au moins 12 sur 14, sans critère inférieur à 1.'], ['b00026','b00027','b00028','b00029','b00038'], images.fastTrack),
        ]},
        { title: 'Spécificités de l’anesthésie régionale', rows: [
          row('Bloc neuraxial', ['Documenter la régression sensitive et motrice.', 'Un bloc persistant plus de 6 heures après la dernière dose impose d’exclure un hématome péridural.'], ['b00030','b00031']),
          row('Marche après rachianesthésie', ['Attendre la résolution des blocs moteur, sensitif et sympathique.', 'Sensibilité périnéale, flexion plantaire et proprioception de l’hallux objectivent le retour fonctionnel.'], ['b00032']),
          row('Bloc périphérique à domicile', [{ text: 'La sortie est possible malgré un bloc moteur persistant si les consignes sont comprises.', children: ['Protéger le membre insensible de la chaleur et des traumatismes', 'Utiliser écharpe, marchette ou béquilles', 'Prendre l’analgésique avant la levée complète du bloc'] }, 'Un contact doit être disponible en cas de problème.'], ['b00033','b00034','b00035','b00036','b00037','b00042','b00043','b00044','b00045']),
        ]},
      ],
    },
    {
      title: 'Complications respiratoires : reconnaître et agir',
      sections: [
        { title: 'Obstruction des voies aériennes', rows: [
          row('Poids clinique', ['En SSPI, les complications touchent environ 24 % des patients.', 'Nausées-vomissements, intervention sur les voies aériennes et hypotension dominent.'], ['b00046','b00047']),
          row('Signes d’obstruction', [{ text: 'Une obstruction partielle associe bruit et tirage ; une obstruction complète peut être silencieuse avec respiration paradoxale.', children: ['Observer le flux d’air et les mouvements thoraciques', 'Ne pas confondre silence et ventilation normale'] }, 'La sédation et les opioïdes diminuent le tonus pharyngé.'], ['b00048','b00049','b00050','b00051','b00052','b00053','b00054']),
          row('Diagnostic différentiel', [{ text: 'Rechercher SAHS, curarisation résiduelle, laryngospasme, corps étranger, œdème, hématome cervical ou paralysie cordale.', children: ['Distinguer collapsus pharyngé et fermeture glottique', 'Inspecter le cou après une chirurgie cervicale'] }, 'L’avancée mandibulaire, l’extension cervicale et une canule peuvent rétablir la ventilation.'], ['b00054','b00055','b00056']),
          row('Risque hypercapnique', ['Une obstruction non levée évolue vers hypoventilation et insuffisance respiratoire hypercapnique.', 'Le traitement porte d’abord sur la perméabilité des voies aériennes.'], ['b00056']),
        ]},
        { title: 'SAHS : dépister et décider le lieu de surveillance', rows: [
          row('Risque', ['Le SAHS est souvent méconnu et multiplie par 2 à 4 les complications périopératoires cardiorespiratoires.', 'L’index apnées-hypopnées classe la sévérité.'], ['b00057','b00058','b00059'], images.sahsSeverity),
          row('STOP-BANG', ['Le questionnaire recherche ronflement, fatigue, apnées observées, HTA, IMC, âge, cou et sexe.', 'Le nombre de réponses positives estime la probabilité de SAHS.'], ['b00058','b00061'], images.stopBang),
          row('Stratification', ['0–2 critères : probabilité faible ; 3–4 : intermédiaire ; au moins 5 : forte.', 'Certaines associations de critères suffisent à classer le risque élevé.'], ['b00058','b00063'], images.stopBangRisk),
          row('Monitorage continu', [{ text: 'Indiqué en cas de SAHS sévère, non traité, comorbidités, chirurgie invasive, événements obstructifs ou forte consommation d’opioïdes.', children: ['Compter désaturations, bradypnées et apnées', 'Choisir une unité capable d’intervenir rapidement'] }, 'La CPAP habituelle est poursuivie si elle est tolérée.'], ['b00065','b00066','b00068','b00069'], images.sahsCare),
          row('Ambulatoire', ['Un SAHS non traité avec opioïdes principaux ou comorbidité mal contrôlée justifie l’hospitalisation.', 'Un patient traité, sans comorbidité instable et avec analgésie non opioïde peut rester candidat.'], ['b00065','b00070','b00072','b00073','b00074'], images.sahsAmbu),
        ]},
        { title: 'Curarisation, laryngospasme et œdème cervical', rows: [
          row('Curarisation résiduelle', [{ text: 'Elle correspond à un TOF < 0,9 et reste fréquente malgré une évaluation qualitative rassurante.', children: ['Mesurer quantitativement plutôt que regarder les réponses', 'Relier la faiblesse aux événements respiratoires'] }, 'Hypothermie, acidose, troubles électrolytiques et défaillances rénale ou hépatique la prolongent.'], ['b00075','b00076']),
          row('Conséquences et antagonisation', ['Obstruction, hypoxémie, microaspiration et réintubation sont plus fréquentes.', 'Utiliser mesure quantitative, anticholinestérase-anticholinergique ou sugammadex selon le curare.'], ['b00076']),
          row('Laryngospasme', ['Administrer O2 à 100 %, arrêter le stimulus et avancer la mandibule.', 'Si persistance : propofol 0,5 mg/kg IV puis succinylcholine 0,1–2 mg/kg IV ou 4 mg/kg IM.'], ['b00077','b00078']),
          row('Œdème à pression négative', ['Une inspiration forcée contre l’obstacle entraîne un transsudat alvéolaire.', 'Intubation, ventilation protectrice avec PEP, diurétique et bêta2-mimétique permettent souvent une résolution en 24–48 heures.'], ['b00079']),
          row('Œdème ou hématome cervical', ['Dyspnée, voix modifiée et stridor annoncent une obstruction possible.', 'Préparer une réintubation éveillée précoce ; en détresse sur hématome, ouvrir la plaie et évacuer la collection.'], ['b00080','b00081']),
        ]},
        { title: 'Hypoxémie : raisonner par mécanisme', rows: [
          row('Cinq mécanismes', [{ text: 'Hypoventilation, inadéquation ventilation-perfusion, shunt, diffusion limitée et faible débit cardiaque structurent le raisonnement.', children: ['Évaluer simultanément ventilation, poumons et circulation', 'Utiliser la réponse à l’oxygène comme indice mécanistique'] }, 'La réponse à l’oxygène aide à les différencier.'], ['b00082','b00083']),
          row('Hypoventilation', ['Obstruction et opioïdes sont les causes usuelles ; une atteinte neurologique ou neuromusculaire est possible.', 'Naloxone 20–40 µg IV par bolus, puis surveillance prolongée car son effet dure 30–120 minutes.'], ['b00084','b00085']),
          row('Ventilation-perfusion', ['L’oxygène améliore habituellement l’hypoxémie.', 'Dans une BPCO sévère, titrer l’O2 pour viser une SpO2 de 88–90 % et limiter l’aggravation de l’hypercapnie.'], ['b00086','b00087']),
          row('Shunt', ['Une zone perfusée non ventilée répond mal à l’oxygène.', 'Atélectasie, pneumonie, SDRA, œdème et aspiration sont les causes majeures ; position semi-assise, spirométrie et CPAP recrutent les alvéoles.'], ['b00088','b00089']),
          row('Diffusion et débit', ['Emphysème, pneumopathie interstitielle et HTAP réduisent la diffusion mais s’améliorent souvent sous O2.', 'Un faible débit augmente l’extraction et amplifie l’effet du sang non oxygéné.'], ['b00090','b00091','b00092','b00093']),
        ]},
      ],
    },
    {
      title: 'Complications cardiovasculaires et surveillance myocardique',
      sections: [
        { title: 'Hypotension et état de choc', rows: [
          row('Première analyse', [{ text: 'Réévaluer pertes, remplissage, drainage, hémoglobine et effet d’un bloc sympathique.', children: ['Reprendre le dossier anesthésique', 'Examiner le site opératoire et les drains'] }, 'Une réponse seulement transitoire au cristalloïde fait rechercher un état de choc.'], ['b00094','b00095','b00096','b00099']),
          row('Causes graves', ['Rechercher saignement, infarctus, embolie pulmonaire, tamponnade, sepsis ou complication chirurgicale.', 'L’ischémie postopératoire est souvent indolore.'], ['b00096','b00099'], images.hypotension),
          row('Escalade', ['Une hypotension persistante appelle renfort, monitorage rapproché et traitement du mécanisme identifié.', 'La destination doit offrir le niveau de soutien requis par le patient.'], ['b00097','b00099','b00150']),
        ]},
        { title: 'Hypertension et arythmies', rows: [
          row('Corriger les déclencheurs', [{ text: 'Traiter d’abord douleur, hypoxémie, hypercapnie, hypothermie, frisson, globe ou sevrage.', children: ['Reprendre les médicaments habituels si approprié', 'Réévaluer la pression après chaque correction'] }, 'Comparer aux valeurs tensionnelles habituelles du patient.'], ['b00100','b00101','b00102']),
          row('Seuils usuels', ['Un traitement est généralement indiqué au-delà de 180 mmHg systolique ou 110 mmHg diastolique.', 'Traiter immédiatement si symptômes, urgence hypertensive ou chirurgie exigeant un contrôle strict.'], ['b00101'], images.hypertensionCauses),
          row('Choix pharmacologique', ['Adapter l’agent à la fréquence cardiaque, aux comorbidités et à la vitesse de contrôle souhaitée.', 'Esmolol, labétalol, hydralazine, énalaprilate, nicardipine et nitrés ont des profils différents.'], ['b00101','b00104','b00106']),
          row('Arythmie', ['Corriger hypoxie, CO2, électrolytes, pH, ischémie et position d’un cathéter central.', 'Une bradycardie mal tolérée relève d’atropine ou glycopyrrolate, bêta-agoniste ou stimulation.'], ['b00107','b00108'], images.hypertensionDrugs),
        ]},
        { title: 'Ischémie myocardique silencieuse', renderChunks: [2, 1], rows: [
          row('Définitions', ['L’infarctus associe élévation de troponine et signes d’ischémie.', 'Le dommage myocardique postopératoire est une élévation ischémique de troponine dans les 30 jours, même sans symptôme ni anomalie ECG.'], ['b00109','b00110','b00111']),
          row('Patients à surveiller', ['Un risque cardiaque majeur ≥ 5 % justifie ECG en SSPI et troponines quotidiennes pendant 48–72 heures.', 'Le suivi concerne notamment âge > 65 ans, RCRI ≥ 1 ou cardiopathie significative entre 45 et 64 ans.'], ['b00112','b00113','b00114','b00116','b00117','b00118','b00119']),
          row('Segment ST', ['L’absence de douleur ne rassure pas en postopératoire immédiat.', 'Chez un patient à haut risque, automatiser si possible la surveillance du segment ST.'], ['b00113','b00119'], images.cardiac),
        ]},
      ],
    },
    {
      title: 'Frisson, réveil, délirium et fonction rénale',
      sections: [
        { title: 'Frisson postopératoire', rows: [
          row('Retentissement', ['Le frisson augmente consommation d’O2, production de CO2, tachycardie, pression et débit cardiaque.', 'Il survient souvent avec l’hypothermie.'], ['b00120','b00121']),
          row('Traitement', ['Commencer par une couverture chauffante si le patient est hypotherme.', 'Mépéridine 0,2–0,4 mg/kg IV, soit 12,5–25 mg, ou dexmédétomidine 0,5 µg/kg sur 2–3 minutes.'], ['b00121','b00122']),
          row('Réévaluation', ['Contrôler température, ventilation, pression et fréquence après chaque intervention.', 'Chez le patient cardiaque, rechercher une ischémie déclenchée par la charge métabolique.'], ['b00121','b00122','b00119']),
        ]},
        { title: 'Éveil retardé et délirium', rows: [
          row('Délai attendu', ['Une réponse à la stimulation devrait apparaître en 60 à 90 minutes.', 'Les anesthésiques résiduels restent la cause la plus fréquente.'], ['b00123','b00124','b00125','b00126']),
          row('Recherche systématique', ['Revoir médicaments et erreurs possibles, température, glycémie, ventilation, gaz du sang, TOF et électrolytes.', 'Rechercher déficit focal, convulsion et état post-critique.'], ['b00126','b00127','b00129'], images.delayed),
          row('Délirium : risque', ['Environ 10 % des patients de plus de 50 ans après chirurgie élective sont concernés.', 'Âge, trouble cognitif et faible scolarité augmentent le risque ; éviter benzodiazépines, anticholinergiques et mépéridine.'], ['b00130','b00131']),
          row('Délirium : prise en charge', ['Vérifier constantes, glycémie, infection, globe, ECG, médicaments et sevrage.', 'Réorientation, calme et éclairage précèdent l’halopéridol 0,5–2 mg, maximum 5 mg, avec vigilance QT.'], ['b00132','b00133','b00134']),
        ]},
        { title: 'Oligurie et rétention', rows: [
          row('Définition', ['L’oligurie correspond à une diurèse < 0,5 mL/kg/h.', 'La distinguer d’un globe vésical, notamment après opioïde intrathécal.'], ['b00135','b00136']),
          row('Trois compartiments', ['Explorer causes pré-rénales, rénales puis post-rénales.', 'Hypovolémie, contraste, rhabdomyolyse, obstacle et dysfonction de sonde sont fréquents.'], ['b00137','b00138','b00140','b00141']),
          row('Contraste', ['Le risque augmente avec insuffisance rénale, hypovolémie, insuffisance cardiaque et diabète.', 'L’hydratation est utile ; bicarbonate, acétylcystéine et mannitol n’ont pas montré de bénéfice supérieur au soluté seul.'], ['b00142']),
          row('Absence totale d’urines', ['Vérifier en premier la perméabilité et la position de la sonde.', 'Envisager ensuite obstruction, lésion urétérale ou complication chirurgicale.'], ['b00143'], images.renal),
        ]},
      ],
    },
  ];

  return {
    matiere: 'Anesthésie-Réanimation', title: 'La salle de soins postopératoires', year: '2026-2027',
    coverSubtitle: 'Du transfert sécurisé à la prise en charge des complications de SSPI',
    imageOmissions: [],
    sourceBlocks: [...new Set(parts.flatMap((part) => part.sections.flatMap((section) => section.rows.flatMap((item) => item.sourceBlocks))))],
    parts,
    synthesis: {
      compactLayout: true,
      chiffres: { headers: ['Repère', 'Valeur'], rows: [
        ['Capacité SSPI', '1,5 à 2 lits par salle d’opération'], ['Aldrete', 'Sortie de phase 1 si ≥ 9/10'],
        ['Fast-track', '≥ 12/14 et aucun critère < 1'], ['Observation', '15 min après opioïde IV et après arrêt O2'],
        ['Rétention', 'Résidu < 300 mL ; cathéter si > 500–600 mL'], ['TOF', 'Curarisation résiduelle si < 0,9'],
        ['HTA à traiter', 'PAS > 180 ou PAD > 110 mmHg'], ['Éveil', 'Réponse attendue en 60–90 min'], ['Oligurie', '< 0,5 mL/kg/h'],
      ]},
      tables: [
        { title: 'Sortie et orientation', headers: ['Situation', 'Décision'], rows: [['Phase 1', 'Score validé, stabilité et surveillance post-sédatif'], ['Ambulatoire', 'Douleur, NVPO, saignement et environnement sûrs'], ['SAHS à risque', 'SpO2 continue, CPAP et hospitalisation selon opioïdes/comorbidités'], ['Bloc régional', 'Régression documentée et protection du membre']] },
        { title: 'Hypoxémie : réponse à l’oxygène', headers: ['Mécanisme', 'Réponse'], rows: [['Hypoventilation', 'Amélioration, mais traiter obstacle ou opioïde'], ['V/Q', 'Amélioration habituelle ; titrer dans BPCO sévère'], ['Shunt', 'Réponse faible ; recruter et traiter la cause'], ['Diffusion', 'Amélioration fréquente'], ['Faible débit', 'Restaurer le transport et la perfusion']] },
      ],
      keyPoints: ['La responsabilité anesthésique persiste jusqu’au relais explicite.', 'La sortie repose sur des critères objectifs et une période d’observation adaptée.', 'Toute obstruction silencieuse ou bruyante exige une action immédiate.', 'Le SAHS module opioïdes, monitorage et possibilité d’ambulatoire.', 'Une curarisation résiduelle est définie par un TOF inférieur à 0,9.', 'L’hypoxémie se raisonne selon cinq mécanismes physiopathologiques.', 'Une hypotension transitoirement corrigée peut révéler un choc.', 'Éveil retardé, délirium et oligurie imposent une recherche systématique réversible.'],
      eclair: ['Transmettre avec SBAR après installation de l’oxygène et du monitorage.', 'Autoriser la sortie de phase 1 avec un score d’Aldrete ≥ 9/10.', 'Respecter 15 minutes d’observation après opioïde IV et après retrait de l’oxygène.', 'Devant obstruction : position, mandibule, canule puis escalade ventilatoire.', 'Devant laryngospasme : O2 à 100 %, arrêt du stimulus, mandibule, propofol puis succinylcholine.', 'Titrer l’oxygène à 88–90 % dans une BPCO sévère.', 'Traiter l’HTA après correction de la douleur et des facteurs déclenchants.', 'Surveiller ECG et troponines 48–72 h chez le patient cardiaque à risque.', 'Réchauffer le frisson hypothermique et limiter sa charge métabolique.', 'Distinguer oligurie et rétention avant toute expansion volémique automatique.'],
    },
  };
}

