const T = (text, why) => [true, text, why];
const F = (text, why) => [false, text, why];
const qcm = (enonce, sourceBlocks, correction_generale, entries, newInformation = null) => ({
  enonce: newInformation ? `${newInformation} ${enonce}` : enonce,
  format: 'qcm', sourceBlocks: Array.isArray(sourceBlocks) ? sourceBlocks : [sourceBlocks], correction_generale,
  ...(newInformation ? { newInformation } : {}),
  items: entries.map(([is_correct, item, justification], index) => ({ lettre: 'ABCDE'[index], enonce: item, is_correct, justification })),
});
const qroc = (enonce, reponse_attendue, sourceBlocks, correction_generale, newInformation = null) => ({
  enonce: newInformation ? `${newInformation} ${enonce}` : enonce,
  format: 'qroc', reponse_attendue, items: [], sourceBlocks: Array.isArray(sourceBlocks) ? sourceBlocks : [sourceBlocks], correction_generale,
  ...(newInformation ? { newInformation } : {}),
});

