function buildDpQroc() { return DP_QROC.map((entry, index) => ({ label: `DP QROC ${index + 1} · ${entry.title}`, vignette: entry.vignette, allowed_voies: ['externe'], questions: entry.questions })); }

function validateSourceBlocks(extract, content) {
  const available = new Set(extract.blocs.filter((block) => block.id).map((block) => block.id));
  const used = [];
  const visit = (value) => {
    if (!value || typeof value !== 'object') return;
    if (Array.isArray(value.sourceBlocks)) used.push(...value.sourceBlocks);
    if (Array.isArray(value)) value.forEach(visit); else Object.values(value).forEach(visit);
  };
  visit(content);
  const missing = [...new Set(used.filter((id) => !available.has(id)))];
  if (missing.length) throw new Error(`Blocs source absents du chapitre 11 : ${missing.join(', ')}`);
}

export function buildChapter11(extract) {
  const series = [...buildIsolatedQcm(), ...buildDpQcm(), ...buildIsolatedQroc(), ...buildDpQroc()];
  const result = { fiche: buildFiche(), flashcards: buildFlashcards(), series };
  validateSourceBlocks(extract, result);
  return result;
}

export default buildChapter11;
